    "jsHint": "JS ต้อง return อ็อบเจ็กต์เพื่อเป็นค่าที่ส่งคืนของ setup ของคอมโพเนนต์ Vue ใช้ ctx.api.get('/me') เพื่อเรียก API ฝั่งแบ็กเอนด์ หลังบันทึกให้เข้าชมหน้าพอร์ทัลเพื่อดูผลลัพธ์จริง",
    "ctxApiRefBody": "ctx.ref(val)              — สร้างตัวแปรแบบ reactive\nctx.computed(fn)          — สร้างพร็อพเพอร์ตี้แบบ computed\nctx.watch(src, cb)        — เฝ้าดูการเปลี่ยนแปลง\nctx.onMounted(fn)         — เมื่อคอมโพเนนต์ถูกเมานต์\nctx.onUnmounted(fn)       — เมื่อคอมโพเนนต์ถูกถอดออก\n\nctx.data.client           — ข้อมูลบัญชีผู้ใช้ (reactive)\nctx.data.token            — Token ปัจจุบัน (reactive)\nctx.data.isDark           — โหมดมืด (reactive)\n\nctx.api.get(path, query)  — คำขอ GET\nctx.api.post(path, body)  — คำขอ POST\nctx.api.put(path, body)   — คำขอ PUT\nctx.api.delete(path)      — คำขอ DELETE\n\nctx.formatBytes(bytes)    — จัดรูปแบบขนาดไฟล์\nctx.formatDate(date)      — จัดรูปแบบวันที่\nctx.copyText(text)        — คัดลอกไปยังคลิปบอร์ด\nctx.elMessage             — การแจ้งเตือนของ Element Plus\nctx.config                — การกำหนดค่าพอร์ทัล (PORTAL_CONFIG)\nctx.moduleId              — ID โมดูลปัจจุบัน\nctx.moduleTitle           — ชื่อโมดูลปัจจุบัน",
